mkdir -p /tmp/work && cat > /tmp/work/r.py <<'EOF'
import json,time,urllib.request,urllib.error
from datetime import datetime,timezone
B="http://localhost:8080";tok=None;notes=[]
def gettok():
    global tok
    while True:
        try:
            r=urllib.request.urlopen(urllib.request.Request(B+"/token",method="POST"));tok=json.load(r)["token"];return
        except urllib.error.HTTPError as e:
            time.sleep(float(e.headers.get("Retry-After") or 1))
def get(p):
    for _ in range(200):
        if not tok: gettok()
        try:
            return json.load(urllib.request.urlopen(urllib.request.Request(B+p,headers={"Authorization":"Bearer "+tok}),timeout=30))
        except urllib.error.HTTPError as e:
            if e.code==401: gettok()
            elif e.code==429: time.sleep(float(e.headers.get("Retry-After") or 1))
            elif e.code==404: return None
            else: notes.append((p,e.code)); time.sleep(0.5)
        except Exception as e: notes.append((p,str(e))); time.sleep(0.5)
    raise SystemExit("fail "+p)
seen={};dup=0;p="/orders?page=1";pages=0
while p:
    d=get(p);pages+=1
    for o in d["items"]:
        if o["id"] in seen:
            dup+=1
            if seen[o["id"]]!=o: notes.append(("diffdup",o,seen[o["id"]]))
        else: seen[o["id"]]=o
    p=d["next"]
lo=datetime(2025,3,1,tzinfo=timezone.utc);hi=datetime(2025,6,1,tzinfo=timezone.utc)
cust={};reg={k:0 for k in["north","south","east","west"]};n=0;stat=set();odd=[]
for o in seen.values():
    stat.add(o["status"])
    if o["status"]!="shipped":continue
    t=datetime.fromisoformat(o["placed_at"].replace("Z","+00:00"))
    if t.tzinfo is None: odd.append(o["placed_at"]); t=t.replace(tzinfo=timezone.utc)
    t=t.astimezone(timezone.utc)
    if not(lo<=t<hi):continue
    c=o["customer_id"]
    if c not in cust: cust[c]=get(f"/customers/{c}")
    cu=cust[c]
    if cu is None: odd.append(("nocust",o)); continue
    v=(o["amount_cents"]*(100-cu["discount_pct"])*2+100)//200
    reg[cu["region"]]+=v;n+=1
r={"total_cents":sum(reg.values()),"order_count":n,"duplicates_skipped":dup,"by_region":reg}
json.dump(r,open("/workspace/result.json","w"),indent=2)
print(r,pages,d["total_pages"],len(seen),stat,odd[:10],len(odd),notes[:10],len(notes))
print({k:v for k,v in list(cust.items())[:3]}, set(type(c["discount_pct"]) for c in cust.values() if c))
EOF
python3 -I /tmp/work/r.py

